dashboard.definition:
{
	"title": "Zero Trust Access",
	"description": "Connect identity, posture, policy, and response signals across the access journey.",
	"inputs": {
		"input_time_range": {
			"options": {
				"defaultValue": "-24h@h,now",
				"token": "time_tok"
			},
			"title": "Time Range",
			"type": "input.timerange"
		}
	},
	"defaults": {
		"visualizations": {
			"global": {
				"showLastUpdated": true,
				"showProgressBar": true
			}
		}
	},
	"visualizations": {
		"viz_header_bg": {
			"type": "splunk.rectangle",
			"options": {
				"fillColor": "#1e293b",
				"strokeColor": "rgba(14,165,233,0.42)"
			}
		},
		"viz_header_icon": {
			"type": "splunk.image",
			"title": "Zero Trust Access",
			"options": {
				"preserveAspectRatio": true,
				"src": "/static/app/splunk-cisco-dashboards/images/overview/secure-networking/zero-trust-access.svg"
			}
		},
		"viz_header": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "transparent",
				"fontColor": "#f1f5f9",
				"markdown": "# Zero Trust Access\nConnect identity, posture, policy, and response signals across the access journey."
			}
		},
		"viz_zta_auth_events": {
			"type": "splunk.singlevalue",
			"title": "ISE Auth Events",
			"dataSources": {
				"primary": "ds_zta_auth_events"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('auth_events') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "#0ea5e9"
			},
			"description": "Total count of ISE authentication events (passed and failed) across all network devices and policy sets, serving as the primary Zero Trust Access activity volume KPI."
		},
		"viz_zta_failed_auth": {
			"type": "splunk.singlevalue",
			"title": "Failed Auth",
			"dataSources": {
				"primary": "ds_zta_failed_auth"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('failed_auth') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "#dc2626"
			},
			"description": "Count of failed ISE authentication attempts , covering credential failures, certificate validation errors, and policy-denied access requests, as the primary Zero Trust denial KPI."
		},
		"viz_zta_failed_pct": {
			"type": "splunk.singlevalueradial",
			"title": "Auth Failure Rate",
			"dataSources": {
				"primary": "ds_zta_failed_pct"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('failed_pct') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "> primary | seriesByName('failed_pct') | lastPoint() | rangeValue(lowerBetter)",
				"unit": "%"
			},
			"context": {
				"lowerBetter": [
					{
						"to": 1,
						"value": "#16a34a"
					},
					{
						"from": 1,
						"to": 5,
						"value": "#f59e0b"
					},
					{
						"from": 5,
						"value": "#dc2626"
					}
				]
			},
			"description": "Authentication failure rate percentage from Cisco ISE , calculated from the observed passed- and failed-authentication event categories, providing a normalized health indicator for the Zero Trust Access enforcement…"
		},
		"viz_zta_feed_health": {
			"type": "splunk.singlevalueradial",
			"title": "ISE Feed Age",
			"dataSources": {
				"primary": "ds_zta_feed_health"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('age_minutes') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "> primary | seriesByName('age_minutes') | lastPoint() | rangeValue(staleness)",
				"unit": "min"
			},
			"context": {
				"staleness": [
					{
						"to": 30,
						"value": "#16a34a"
					},
					{
						"from": 30,
						"to": 90,
						"value": "#f59e0b"
					},
					{
						"from": 90,
						"value": "#dc2626"
					}
				]
			},
			"description": "Staleness monitor for the Cisco ISE RADIUS authentication syslog feed. Any active corporate network generates RADIUS auth events continuously - silence beyond 30 minutes indicates the MnT syslog target has broken, not…"
		},
		"viz_zta_auth_outcome": {
			"type": "splunk.area",
			"title": "Authentication Outcome Trend",
			"dataSources": {
				"primary": "ds_zta_auth_outcome_trend"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#6ee7b7",
					"#fda4af",
					"#cbd5e1"
				],
				"stackMode": "stacked",
				"lineWidth": 3,
				"nullValueDisplay": "gaps"
			},
			"description": "Charts Cisco ISE authentication outcomes over time, split into success and failure series for Zero Trust Access monitoring."
		},
		"viz_zta_radius_latency": {
			"type": "splunk.area",
			"title": "RADIUS Latency by ISE Node",
			"dataSources": {
				"primary": "ds_zta_radius_latency"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#7dd3fc",
					"#6ee7b7",
					"#fcd34d",
					"#fda4af"
				],
				"lineWidth": 3,
				"nullValueDisplay": "gaps"
			},
			"description": "Tracks average RADIUS request processing latency in milliseconds per ISE node, the most direct indicator of authentication performance visible to end users and NADs."
		},
		"viz_zta_ztna_status": {
			"type": "splunk.area",
			"title": "ZTNA Connection Status",
			"dataSources": {
				"primary": "ds_zta_ztna_status"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#6ee7b7",
					"#fcd34d",
					"#fda4af",
					"#cbd5e1"
				],
				"stackMode": "stacked",
				"lineWidth": 3,
				"nullValueDisplay": "gaps"
			},
			"description": "Hourly trend of Cisco SSE ZTNA connection statuses over time, enabling operators to track ZTNA adoption growth, detect access disruptions, and correlate denial spikes with policy or infrastructure changes."
		},
		"viz_zta_auth_by_device": {
			"type": "splunk.table",
			"title": "Auth Failure Rate by Network Device",
			"dataSources": {
				"primary": "ds_zta_auth_by_device"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Per- network access device (NAD) ISE authentication failure rate , identifying which switches, WLCs, or VPN concentrators are contributing most to failed authentications and may require investigation."
		},
		"viz_zta_failure_reasons": {
			"type": "splunk.bar",
			"title": "Top Authentication Failure Reasons",
			"dataSources": {
				"primary": "ds_zta_failure_reasons"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"legendDisplay": "off",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#dc2626"
				]
			},
			"description": "Ranks ISE authentication failure reasons by site/location and network device so access-policy failures become actionable instead of a single failed-auth count."
		},
		"viz_zta_user_cross_source": {
			"type": "splunk.table",
			"title": "Cross-Source User Activity",
			"dataSources": {
				"primary": "ds_zta_user_cross_source"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Cross-source user/identity activity correlation spanning ISE NAC, Cisco ZTNA, and FMC firewall layers, providing a unified per-user view of how many Zero Trust enforcement layers an identity is active across and whether…"
		},
		"viz_zta_ravpn_connection_rate": {
			"type": "splunk.area",
			"title": "Remote Access VPN Clients, Sessions, and Connect Rate",
			"dataSources": {
				"primary": "ds_zta_ravpn_connection_rate"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#7dd3fc",
					"#67e8f9",
					"#6ee7b7",
					"#fda4af"
				],
				"lineWidth": 3,
				"nullValueDisplay": "gaps"
			},
			"description": "Tracks remote-access VPN clients, sessions, successful connections, and failed connections in 15-minute intervals."
		},
		"viz_zta_ravpn_posture_alerts": {
			"type": "splunk.table",
			"title": "Remote Access VPN Posture Alerts and Logs",
			"dataSources": {
				"primary": "ds_zta_ravpn_posture_alerts"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Surfaces RaVPN posture failures, warnings, alerts, and operational log reasons with user, profile, region, and device context."
		},
		"viz_design_context": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "#1e293b",
				"fontColor": "#f1f5f9",
				"markdown": "**Audience:** Identity, network-security, and SOC teams  •  **Sources:** Cisco ISE authentication and network-device enforcement telemetry  •  **Reading guide:** Compare authentication volume and failure pressure before investigating devices and policy.  •  **Freshness:** Uses the dashboard time range"
			}
		},
		"viz_design_section": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "#1e293b",
				"fontColor": "#f1f5f9",
				"markdown": "### Access posture\nCompare authentication volume and failure pressure before investigating devices and policy."
			}
		}
	},
	"dataSources": {
		"ds_zta_auth_events": {
			"name": "Secure Networking chain - ZTA auth event count",
			"options": {
				"ref": "secure_networking_zta_ise_auth_events_count",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_zta_failed_auth": {
			"name": "Secure Networking chain - ZTA failed auth count",
			"options": {
				"ref": "secure_networking_zta_ise_failed_auth_count",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_zta_failed_pct": {
			"name": "Secure Networking chain - ZTA failure rate",
			"options": {
				"ref": "secure_networking_zta_ise_failed_auth_pct",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_zta_feed_health": {
			"name": "Feed Monitor - ISE - RADIUS Syslog Staleness - Signal Rail KPI",
			"options": {
				"ref": "feed_monitor_ise_syslog_staleness",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_zta_auth_outcome_trend": {
			"name": "Secure Networking chain - ZTA auth outcome trend",
			"options": {
				"ref": "secure_networking_zta_auth_outcome_trend",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_zta_radius_latency": {
			"name": "Security Resilience - ISE RADIUS Request Latency",
			"options": {
				"ref": "security_resilience_ise_radius_latency",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_zta_ztna_status": {
			"name": "Secure Networking - ZTA ZTNA Connection Status Trend",
			"options": {
				"ref": "secure_networking_zta_ztna_connection_status_trend",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_zta_auth_by_device": {
			"name": "Secure Networking chain - ZTA auth failure by device",
			"options": {
				"ref": "secure_networking_zta_ise_auth_by_device_fail_rate",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_zta_failure_reasons": {
			"name": "Secure Networking chain - ZTA failure reasons by site",
			"options": {
				"ref": "secure_networking_zta_failure_reasons_by_site",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_zta_user_cross_source": {
			"name": "Secure Networking - ZTA User Activity Cross-Source Correlation",
			"options": {
				"ref": "secure_networking_zta_user_activity_cross_source",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_zta_ravpn_connection_rate": {
			"name": "Secure Networking - ZTA RaVPN Connection Rate and Clients",
			"options": {
				"ref": "secure_networking_zta_ravpn_connection_rate",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_zta_ravpn_posture_alerts": {
			"name": "Secure Networking - ZTA RaVPN Posture Alerts and Logs",
			"options": {
				"ref": "secure_networking_zta_ravpn_posture_alerts",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		}
	},
	"layout": {
		"globalInputs": [
			"input_time_range"
		],
		"layoutDefinitions": {
			"layout_overview": {
				"options": {
					"backgroundColor": "#020617",
					"display": "auto-scale",
					"height": 1706,
					"width": 1440
				},
				"structure": [
					{
						"item": "viz_header_bg",
						"position": {
							"x": 20,
							"y": 0,
							"w": 1400,
							"h": 88
						},
						"type": "block"
					},
					{
						"item": "viz_header_icon",
						"position": {
							"x": 36,
							"y": 14,
							"w": 56,
							"h": 56
						},
						"type": "block"
					},
					{
						"item": "viz_header",
						"position": {
							"x": 108,
							"y": 4,
							"w": 1292,
							"h": 76
						},
						"type": "block"
					},
					{
						"item": "viz_design_context",
						"position": {
							"x": 20,
							"y": 100,
							"w": 1400,
							"h": 64
						},
						"type": "block"
					},
					{
						"item": "viz_design_section",
						"position": {
							"x": 20,
							"y": 176,
							"w": 1400,
							"h": 54
						},
						"type": "block"
					},
					{
						"item": "viz_zta_auth_events",
						"position": {
							"x": 20,
							"y": 242,
							"w": 335,
							"h": 200
						},
						"type": "block"
					},
					{
						"item": "viz_zta_failed_auth",
						"position": {
							"x": 375,
							"y": 242,
							"w": 335,
							"h": 200
						},
						"type": "block"
					},
					{
						"item": "viz_zta_failed_pct",
						"position": {
							"x": 730,
							"y": 242,
							"w": 335,
							"h": 200
						},
						"type": "block"
					},
					{
						"item": "viz_zta_feed_health",
						"position": {
							"x": 1085,
							"y": 242,
							"w": 335,
							"h": 200
						},
						"type": "block"
					},
					{
						"item": "viz_zta_auth_outcome",
						"position": {
							"x": 20,
							"y": 458,
							"w": 690,
							"h": 280
						},
						"type": "block"
					},
					{
						"item": "viz_zta_radius_latency",
						"position": {
							"x": 730,
							"y": 458,
							"w": 690,
							"h": 280
						},
						"type": "block"
					},
					{
						"item": "viz_zta_ztna_status",
						"position": {
							"x": 20,
							"y": 754,
							"w": 690,
							"h": 280
						},
						"type": "block"
					},
					{
						"item": "viz_zta_auth_by_device",
						"position": {
							"x": 730,
							"y": 754,
							"w": 690,
							"h": 300
						},
						"type": "block"
					},
					{
						"item": "viz_zta_failure_reasons",
						"position": {
							"x": 20,
							"y": 1070,
							"w": 690,
							"h": 280
						},
						"type": "block"
					},
					{
						"item": "viz_zta_user_cross_source",
						"position": {
							"x": 730,
							"y": 1070,
							"w": 690,
							"h": 300
						},
						"type": "block"
					},
					{
						"item": "viz_zta_ravpn_connection_rate",
						"position": {
							"x": 20,
							"y": 1386,
							"w": 690,
							"h": 280
						},
						"type": "block"
					},
					{
						"item": "viz_zta_ravpn_posture_alerts",
						"position": {
							"x": 730,
							"y": 1386,
							"w": 690,
							"h": 300
						},
						"type": "block"
					}
				],
				"type": "absolute"
			}
		},
		"options": {
			"showTitleAndDescription": false,
			"submitButton": false,
			"submitOnDashboardLoad": true
		},
		"tabs": {
			"items": [
				{
					"label": "overview",
					"layoutId": "layout_overview"
				}
			]
		}
	},
	"applicationProperties": {
		"collapseNavigation": false,
		"hideEdit": false,
		"hideExport": false
	}
}
